from __future__ import absolute_import

from builtins import str
import re
import base64
from taf.ul.trs_e2e_fw.lib.utils.decorators import check_rat
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from taf.ul.trs_e2e_fw.lib.oam.admin.parameters import Parameters
from taf.ul.trs_e2e_fw.lib.oam.admin.admin_factory import AdminBaseClass
from taf.ul.trs_e2e_fw.lib.utils.connection_manager.communicator import Communicator


logger = BackgroundLogger.Instance()


class Certificate(AdminBaseClass):
    """Certificate"""
    def __init__(self):
        super(Certificate, self).__init__()

    @check_rat
    def certificate_configure(self, **kwargs):
        """Configure certificate"""
        operation = kwargs.get("operation", "''")
        timeout = kwargs.get("timeout", 60)
        alias = kwargs.get("alias", "default")
        kwargs = {key: value for key, value in list(kwargs.items()) if key not in ["operation", "timeout", "alias"]}

        logger.debug("Performing operation  {}...".format(operation.upper().replace("_", " ")))
        if operation.lower() == 'install_cmp_certificate':
            key_pool_type = kwargs.get('key_pool_type', "RSA")
            return self._install_cmp_certificate(timeout, alias, key_pool_type)
        elif operation.lower() == 'update_certificate_revocation_list':
            return self._update_certificate_revocation_list(timeout, alias, **kwargs)
        elif operation.lower() == 'restore_vendor_certificate':
            return self._restore_vendor_certificate(timeout, alias)
        elif operation.lower() == 'get_certificate_list':
            return self._get_certificate_list(timeout, alias, **kwargs)
        elif operation.lower() == 'get_certificate_details':
            return self._get_certificate_details(timeout, alias, **kwargs)
        elif operation.lower() == 'get_certificate_revocation_list':
            return self._get_certificate_revocation_list(timeout, alias, **kwargs)
        elif operation.lower() == 'get_certificate_file':
            return self._get_certificate_file(timeout, alias, **kwargs)
        elif operation.lower() == 'install_certificate':
            return self._install_certificate(timeout, alias, **kwargs)
        elif operation.lower() == 'set_certificate_automatic_managment':
            return self._set_certificate_automatic_managment(timeout, alias, **kwargs)
        elif operation.lower() == 'cmp_update_key':
            key_pool_type = kwargs.get('key_pool_type', "RSA")
            return self._cmp_update_key(timeout, alias, key_pool_type)
        elif operation.lower() == 'delete_cert':
            return self._delete_certificate(timeout, alias, **kwargs)
        elif operation.lower() == 'get_finger_print':
            source, subject, typ = self._get_cert_params_from_kwargs(**kwargs)
            return self._get_fingerprint(source, subject, typ, timeout, alias)
        else:
            raise Exception("Operation {} not supported".format(operation))

    def _install_cmp_certificate(self, timeout, alias, key_pool_type):
        """
        Installs CMP certificate.
        NOTE: Due to network issue in WebEm API's while communicating with external  sources,
        retry is added for '_install_cmp_certificate' operation.
        If this operation throws exception CMP server IP fetched from WebEM will be pinged to check the reachibility
        and retry the operation until its succeeded with maximum retry of 3 times.
        """
        attempt = 1
        e = None
        while attempt <= 3:
            try:
                return self.factory.admin.cmp_initialize_certificate(timeout=timeout, connection=alias,
                                                                     key_pool_type=key_pool_type)
            except Exception as e:
                logger.debug("exception is :{} in attempt :{}".format(e, attempt))
                param_path = "CERTH-1/CMP-1:serverHost"
                self.cmp_server_ip = Parameters().get_parameter(param_path=param_path, alias=alias)
                logger.info("CP SERVER IP IS : {}".format(self.cmp_server_ip))
                command = "ping {} -w 2".format(self.cmp_server_ip)
                logger.info("ping command is :{}".format(command))
                _, _, ping_status = Communicator().command_executor(command)
                logger.info("ping status is :{}".format(ping_status))
                if ping_status:
                    logger.error("CMP Server IP not reachable in attempt : {}".format(attempt))
                attempt += 1
        else:
            raise Exception(str(e).split("Status reached:")[1].split("ErrorCode")[0].strip())

    def _update_certificate_revocation_list(self, timeout, alias, **kwargs):
        """
        Updates Certificate Revocation list.
        NOTE: Due to network issue in WebEm API's while communicating with external  sources,
        retry is added for '_update_certificate_revocation_list' operation.
        If this operation throws exception CMP server IP fetched from WebEM will be pinged to check the reachibility
        and retry the operation until its succeeded with maximum retry of 3 times.
        """
        domain_type = kwargs.get('domain_type', "3GPP")
        attempt = 1
        while attempt <= 3:
            try:
                return self.factory.admin.update_certificate_revocation_list(domain_type=domain_type, timeout=timeout,
                                                                             connection=alias)
            except Exception as e:
                logger.debug("exception is :{} in attempt :{}".format(e, attempt))
                param_path = "CERTH-1/CMP-1:serverHost"
                self.cmp_server_ip = Parameters().get_parameter(param_path=param_path, alias=alias)
                logger.info("CP SERVER IP IS : {}".format(self.cmp_server_ip))
                command = "ping {} -w 2".format(self.cmp_server_ip)
                logger.info("ping command is :{}".format(command))
                _, _, ping_status = Communicator().command_executor(command)
                logger.info("ping status is :{}".format(ping_status))
                if ping_status:
                    logger.error("CMP Server IP not reachable in attempt : {}".format(attempt))
                attempt += 1
        else:
            raise Exception("Update certificate revocation list failed after maximum retries")

    def _restore_vendor_certificate(self, timeout, alias):
        self.factory.admin.restore_vendor_certificate(timeout, alias)

    def _get_certificate_list(self, timeout, alias, **kwargs):
        cert_type = kwargs['type']
        return self.factory.admin.get_certificate_list(cert_type=cert_type, timeout=timeout,
                                                       connection=alias)

    def _get_certificate_details(self, timeout, alias, **kwargs):
        logger.debug("Get cert dets")
        source, subject, typ = self._get_cert_params_from_kwargs(**kwargs)
        fingerprint = self._get_fingerprint(source, subject, typ, timeout, alias)
        response = self.factory.admin.get_certificate_details(fingerprint=fingerprint,
                                                              timeout=timeout, connection=alias)
        return response

    def _get_all_certificates_params_from_im(self, alias, timeout):
        logger.info("Getting all available certificates from IM")
        distname = "//CERTIFICATE_L-*"
        return Parameters().query_admin_infomodel(query="get list {}".format(distname),
                                                  timeout=timeout, alias=alias)

    def _get_fingerprint(self, source, subject, typ, timeout, alias):
        cert_param_dict = self._get_all_certificates_params_from_im(alias, timeout)
        for cert_params in cert_param_dict:
            try:
                fingerprint = cert_params["fingerPrint"]
                logger.debug(fingerprint)
                cert_found = self._check_if_certificate_matches(cert_params, source, subject, typ)
                if cert_found:
                    logger.debug('Matched fingerprint: {}'.format(fingerprint))
                    return fingerprint
            except Exception as e:
                if "No such a distName" in e:
                    pass
        raise Exception("None of the available certificates matched with the given source, "
                        "subject and type")

    def _check_if_certificate_matches(self, cert_params, source, subject, typ):
        cert_found = True
        extracted_subj = re.findall(r"CN\s*=\s*.*", cert_params["issuedTo"], re.DOTALL)[0]
        logger.debug('source, typ, extracted_subj')
        logger.debug('{} {} {}'.format(source, typ, extracted_subj))
        logger.debug('{} {} {}'.format(cert_params["source"], cert_params["type"], subject))
        # logger.debug('source {} {}'.format(source, cert_params["source"]))
        # logger.debug('subject {} {}'.format(subject, extracted_subj))
        # logger.debug('typ {} {}'.format(typ, cert_params["type"]))
        for param, value in list(cert_params.items()):
            if cert_params["source"] != source:
                cert_found = False
                break
            if subject is not None:
                if extracted_subj != 'CN = {}'.format(subject):
                    cert_found = False
                    break
            if typ is not None:
                if cert_params["type"] != typ:
                    cert_found = False
                    break
        return cert_found

    def _get_certificate_revocation_list(self, timeout, alias, **kwargs):
        domain_type = kwargs.get('domain_type', "3GPP")
        return self.factory.admin.get_certificate_revocation_list(domain_type=domain_type.upper(), timeout=timeout,
                                                                  connection=alias)

    def _get_certificate_file(self, timeout, alias, **kwargs):
        source, subject, typ = self._get_cert_params_from_kwargs(**kwargs)
        target_file_name = kwargs['target_file_name']
        fingerprint = self._get_fingerprint(source, subject, typ, timeout, alias)
        return self.factory.admin.get_certificate_file(fingerprint=fingerprint,
                                                       target_file_name=target_file_name,
                                                       timeout=60, connection=alias)

    def _install_certificate(self, timeout, alias, **kwargs):
        """
        Installs certificate.
        NOTE: Due to network issue in WebEm API's while communicating with external  sources,
        retry is added for '_install_certificate' operation.
        If this operation throws exception CMP server IP fetched from WebEM will be pinged to check the reachibility
        and retry the operation until its succeeded with maximum retry of 3 times.
        """
        cert_file = kwargs.get('cert_file')
        cert_type = kwargs.get('cert_type')
        cert_format = kwargs.get('cert_format')
        password = kwargs.get('password', None)
        key_pool_type = kwargs.get('key_pool_type')
        attempt = 1
        while attempt <= 3:
            try:
                return self.factory.admin.install_certificate(
                    cert_file=cert_file, cert_type=cert_type, cert_format=cert_format,
                    password=password, timeout=timeout, connection=alias, key_pool_type=key_pool_type)
            except Exception as e:
                result = str(e)
                result_string = result.split("Status reached: ")[1].split(".")[0].strip()
                logger.debug("exception is :{} in attempt :{}".format(e, attempt))
                param_path = "CERTH-1/CMP-1:serverHost"
                self.cmp_server_ip = Parameters().get_parameter(param_path=param_path, alias=alias)
                logger.info("CP SERVER IP IS : {}".format(self.cmp_server_ip))
                command = "ping {} -w 2".format(self.cmp_server_ip)
                logger.info("ping command is :{}".format(command))
                _, _, ping_status = Communicator().command_executor(command)
                logger.info("ping status is :{}".format(ping_status))
                if ping_status:
                    logger.error("CMP Server IP not reachable in attempt : {}".format(attempt))
                attempt += 1
        else:
            raise Exception(result_string)

    def _set_certificate_automatic_managment(self, timeout, alias, **kwargs):
        reference_number = kwargs['reference_number']
        preshared_key = kwargs['preshared_key']
        key_pool_type = kwargs.get('key_pool_type', "RSA")
        self.factory.admin.set_certificate_automatic_management(reference_number, preshared_key, timeout=timeout,
                                                                connection=alias, key_pool_type=key_pool_type)
        self._install_cmp_certificate(timeout=timeout, alias=alias, key_pool_type=key_pool_type)

    def _cmp_update_key(self, timeout, alias, key_pool_type):
        self.factory.admin.cmp_update_key(timeout=timeout, connection=alias, key_pool_type=key_pool_type)

    def _delete_certificate(self, timeout, alias, **kwargs):
        all_certs = kwargs.get('all_certs', False)
        if not all_certs:
            source, subject, typ = self._get_cert_params_from_kwargs(**kwargs)
            fingerprint = self._get_fingerprint(source, subject, typ, timeout, alias)
            self.factory.admin.delete_certificate(fingerprint, timeout=timeout, connection=alias)
        else:
            self._restore_vendor_certificate(timeout, alias)
            cert_param_dict = self._get_all_certificates_params_from_im(alias, timeout)
            logger.debug('All Available Certificates fingerprints')
            logger.debug(str(cert_param_dict))
            for cert in cert_param_dict:
                fingerprint = cert['fingerPrint']
                if cert['source'].lower() != 'vendor':
                    logger.info('Deleting cert with fingerprint {}'.format(fingerprint))
                    self.factory.admin.delete_certificate(fingerprint, timeout=timeout,
                                                          connection=alias)
                else:
                    logger.info('Ignored vendor cert with fingerprint {}'.format(fingerprint))

    def _get_cert_params_from_kwargs(self, **kwargs):
        source = kwargs.get("source")
        subject = kwargs.get("subject", None)
        typ = kwargs.get("type", None)
        if not source:
            raise Exception('source argument is mandatory. Can be Operator or Vendor')
        return source, subject, typ

    def close_netconf_radio_session(self, **kwargs):
        """
        Close Netconf radio session.

        :param string target_distname: Dist name for the object to be closed.
        :param Union[int,str] timeout: Timeout for the operation, 60 second by default.
        :param bool detailed_output: return full request response when True, defaults set to False.
        :param Union[AdminConnection,str] connection: AdminConnection.
        :return Union[str,dict]: Result operation result as string ie. Completed, Failed, sometimes empty or full response dict.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-closeNetconfRadioSession.html
        """
        dn = kwargs['distname']
        timeout = kwargs.get('timeout', 60)
        detailed_output = kwargs.get('detailed_output', False)
        alias = kwargs.get('alias', 'default')
        return self.factory.admin.close_netconf_radio_session(target_distname=dn, timeout=timeout,
                                                              detailed_output=detailed_output, connection=alias)

    def get_netconf_radio_sessions(self, **kwargs):
        """
        Get Netconf radio sessions as a JSON file.

        :param string output_file_name: Path to a file.
        :param Union[int,str] timeout: Timeout for the operation, 60 second by default.
        :param bool detailed_output: return full request response when True, defaults set to False.
        :param Union[AdminConnection,str] connection: AdminConnection.
        :return Union[str,dict]: Result operation result as string ie. Completed, Failed, sometimes empty or full response dict.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-getNetconfRadioSessions.html
        """
        output_file_name = kwargs.get('output_file_name', './execution_logs/net_conf_radio_sessions.txt')
        timeout = kwargs.get('timeout', 60)
        detailed_output = kwargs.get('detailed_output', False)
        alias = kwargs.get('alias', 'default')
        return self.factory.admin.get_netconf_radio_sessions(output_file_name=output_file_name, timeout=timeout,
                                                             detailed_output=detailed_output, connection=alias)

    def query_netconf_radio_accounts(self, **kwargs):
        """
        Query Netconf radio accounts.

        :param list target_distnames: List of oru radio DN.
        :param Union[int,str] timeout: Timeout for the operation, 60 second by default.
        :param bool detailed_output: return full request response when True, defaults set to False.
        :param Union[AdminConnection,str] connection: AdminConnection.
        :return Union[str,dict]: Result operation result as string ie. Completed, Failed, sometimes empty or full response dict.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-queryNetconfRadioAccounts.html
        """
        dn = kwargs['distnames']
        timeout = kwargs.get('timeout', 60)
        detailed_output = kwargs.get('detailed_output', True)
        alias = kwargs.get('alias', 'default')
        if isinstance(dn, str):
            dn = [dn]

        response = self.factory.admin.query_netconf_radio_accounts(target_distnames=dn, timeout=timeout,
                                                               detailed_output=detailed_output, connection=alias)
        result=base64.b64decode(response['outputFileContent'])
        return result

